posts = []
for index, line in enumerate(SOURCE.strip().splitlines(), 1):
    category, title, text = line.split('|', 2)
    posts.append({'id': f'{index:03}', 'category': category, 'title': title, 'text': text, 'status': 'prepared'})
assert len(posts) == 100, len(posts)
assert len({p['text'] for p in posts}) == 100
assert all(100 <= len(p['text']) <= 600 for p in posts)
(HERE / 'posts.json').write_text(json.dumps(posts, indent=2, ensure_ascii=False), encoding='utf-8')
cards = ''.join(f'<article id="post-{p["id"]}"><small>{p["id"]} / 100 · {html.escape(p["category"])}</small><h2>{html.escape(p["title"])}</h2><p>{html.escape(p["text"])}</p><button onclick="navigator.clipboard.writeText(this.previousElementSibling.innerText)">Copy post</button></article>' for p in posts)
page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DigiStayBook · 100 Facebook posts</title><style>body{margin:0;background:#f7f2e8;color:#14181b;font:17px/1.6 system-ui}main{max-width:850px;margin:auto;padding:32px 20px}h1{font-size:34px;line-height:1.2}article{background:#fffdf8;border:1px solid #ddd3c4;border-radius:12px;padding:24px;margin:20px 0}h2{font-size:21px;margin:8px 0}small{color:#765744}button{background:#b4472a;color:white;border:0;border-radius:6px;padding:10px 15px;cursor:pointer}.note{padding:16px;background:#ece2d2;border-radius:8px}input{font:inherit;padding:12px;width:100%;box-sizing:border-box}</style><main><h1>100 Facebook posts for DigiStayBook</h1><p>Prepared 17 October 2026 · Public Page content · Text only</p><p class="note">Product wording checked against the live DigiStayBook website. Hosting tips are general suggestions, not customer testimonials or guarantees. The publication log records actual Facebook outcomes; this library alone does not establish publication.</p><input placeholder="Search posts" oninput="document.querySelectorAll('article').forEach(a=>a.hidden=!a.innerText.toLowerCase().includes(this.value.toLowerCase()))">'''+cards+'</main></html>'
(HERE / 'library.html').write_text(page, encoding='utf-8')
print(json.dumps({'posts': len(posts), 'unique': len({p['text'] for p in posts}), 'folder': str(HERE)}))
